use quartz_kernel::{CELLS,CENTER,recovery::Recovery};
#[test] fn parity(){for s in 0..64usize{let d:Vec<_>=(0..CELLS).filter(|&i|Recovery::outer(i)&&(i+s)%(s%7+1)==0).map(|i|(i,((i*7+s)%100+1)as u8)).collect();let mut a=Recovery::new([s as u32,40,90]).shock(&d).unwrap();for _ in 0..32{let b=a.fixed_step().unwrap();assert_eq!(b,a.step().unwrap());assert_eq!(b,a.parallel_step().unwrap());let gain:u32=b.health().iter().zip(a.health()).map(|(&x,&y)|u32::from(x-y)).sum();assert_eq!(gain,a.energy().iter().sum::<u32>()-b.energy().iter().sum::<u32>());assert!(gain<=24);assert_eq!(b.health()[CENTER],100);a=b;}}}
